def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Adaptive endgame for the last 5 rounds
    if n >= 95:
        if n == 95:
            return 'C'
        if n == 96:
            if history[95][1] == 'D':
                return 'D'
            return 'C'
        if n == 97:
            if history[95][1] == 'D' or history[96][1] == 'D':
                return 'D'
            return 'C'
        if n == 98:
            if (history[95][1] == 'D' or 
                history[96][1] == 'D' or 
                history[97][1] == 'D'):
                return 'D'
            return 'C'
        return 'D'

    # Main game: generous Tit-for-Tat
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        recent = history[-10:] if n >= 10 else history
        opp_c = sum(1 for a, b in recent if b == 'C')
        if opp_c >= 7:
            return 'C'
        return 'D'
    return 'C'
